def find_path(graph, start, goal):
    from collections import deque, defaultdict

    def hill_climbing_search(graph, start, goal, visited=None):
        if visited is None:
            visited = set()
        if start == goal:
            return [start]
        visited.add(start)
        neighbors = graph.get(start, [])
        for neighbor in neighbors:
            if neighbor not in visited:
                path = hill_climbing_search(graph, neighbor, goal, visited)
                if path:
                    return [start] + path
        return None

    # Initialize the search if the goal is not already in the graph
    if goal not in graph:
        return None

    return hill_climbing_search(graph, start, goal)

