def find_path(graph, start, goal):
    # Initialize queues for forward and backward search
    forward_queue = [[start]]
    backward_queue = [[goal]]

    # Set to keep track of visited nodes
    forward_visited = {start}
    backward_visited = {goal}

    # Create dictionaries to keep track of parent nodes
    forward_parent = {start: None}
    backward_parent = {goal: None}

    # While both queues are not empty
    while forward_queue and backward_queue:
        # Get the next level of nodes to expand for forward and backward search
        current_forward = forward_queue.pop(0)
        current_backward = backward_queue.pop(0)

        # Check if the nodes in the current level contain the goal
        if current_forward[-1] == goal:
            return reconstruct_path(current_forward, forward_parent)
        if current_backward[-1] == start:
            return reconstruct_path(current_backward[::-1], backward_parent)[::-1]

        # Expand the current nodes
        for neighbor in graph[current_forward[-1]]:
            if neighbor not in forward_visited:
                forward_visited.add(neighbor)
                forward_queue.append(current_forward + [neighbor])
                forward_parent[neighbor] = current_forward[-1]

        for neighbor in graph[current_backward[-1]]:
            if neighbor not in backward_visited:
                backward_visited.add(neighbor)
                backward_queue.append(current_backward + [neighbor])
                backward_parent[neighbor] = current_backward[-1]

    # If no path is found
    return None

def reconstruct_path(path, parent_dict):
    reversed_path = path[::-1]
    current = reversed_path[0]
    path = []
    while current is not None:
        path.append(current)
        current = parent_dict.get(current)
    return path[::-1]

