def find_path(graph, start, goal):
    def ids_search(max_depth):
        fringe = [(start, [start])]
        while fringe:
            current, path = fringe.pop(0)
            if current == goal:
                return path
            if current in graph:
                for neighbor in graph[current]:
                    if len(path) <= max_depth and neighbor not in path:
                        new_path = path + [neighbor]
                        fringe.append((neighbor, new_path))
            # Limit search depth
            if len(path) == max_depth:
                return ids_search(max_depth + 1)
        return None

    # Initialize search from maximum depth of 1
    return ids_search(1)

