def find_path(graph, start, goal):
    # Initialize a stack for the depth-first search
    stack = deque([(start, [start])])
    visited = set()

    while stack:
        (node, path) = stack.pop()
        if node not in visited:
            visited.add(node)
            if node == goal:
                return path
            for neighbor in graph.get(node, []):
                if neighbor not in visited:
