def find_path(graph, start, goal):
    def ids(current_depth):
        fringe = [(start, [start])]
        while fringe:
            (node, path) = fringe.pop(0)
            if node == goal:
                return path
            for next_node in graph[node]:
                if next_node not in path:
                    fringe.append((next_node, path + [next_node]))
            # Limit the search depth
            if current_depth > 0:
                fringe.sort(key=lambda x: len(x[1]), reverse=True)
                fringe = fringe[:current_depth]
        return None

    # Start with a small depth and increase it until a path is found
    for depth in range(1, len(graph) + 1):
        path = ids(depth)
        if path:
            return path
    return None

