import heapq
from collections import defaultdict

def find_path(graph, start, goal):
    # Step 1: Add a new node (sink) and connect all nodes to it with a zero-weight edge.
    sink = 'sink'
    graph[sink] = []

    # Step 2: Run Bellman-Ford multiple times to compute the shortest paths from the sink to all other nodes.
    distances = defaultdict(lambda: float('inf'))
    distances[sink] = 0
    for _ in range(len(graph)):
        for u, neighbors in graph.items():
            for v in neighbors:
                if distances[u] + 1 < distances[v]:
                    distances[v] = distances[u] + 1

    # Step 3: Adjust weights of all edges using the shortest distances.
    for u in graph:
        for v in graph[u]:
            graph[u][v] = graph[u][v] + distances[u] - distances[v]

    # Step 4: Run Dijkstra's algorithm from the start node to the goal node.
    frontier = [(0, start)]
    visited = set()
    came_from = {start: None}
    while frontier:
        current_distance, current_node = heapq.heappop(frontier)

        if current_node == goal:
            path = []
            while current_node is not None:
                path.append(current_node)
                current_node = came_from[current_node]
            return path[::-1]  # Return the path in reverse order

        if current_node in visited:
            continue
        visited.add(current_node)

        for next_node in graph[current_node]:
            if next_node not in visited:
                new_distance = current_distance + graph[current_node][next_node]
                if new_distance < distances[next_node]:
                    distances[next_node] = new_distance
                    came_from[next_node] = current_node
                    heapq.heappush(frontier, (new_distance, next_node))

    # Step 5: If the goal is unreachable, return None
    return None

