def find_path(graph, start, goal):
    # Helper function to find the shortest path using Bidirectional Search
    def bidirectional_search(source, target):
        # Set up the frontier for the search
        open_set_frontier = {source}
        open_set_target = {target}
        closed_set_frontier = set()
        closed_set_target = set()
        # Initialize the path dictionaries
        path_frontier = {source: [source]}
        path_target = {target: [target]}

        # Set up the path cost
        cost_frontier = {source: 0}
        cost_target = {target: 0}

        while open_set_frontier and open_set_target:
            # Choose the node in the open set with the lowest cost for the frontier
            current_frontier = min(open_set_frontier, key=lambda node: cost_frontier[node])
            current_target = min(open_set_target, key=lambda node: cost_target[node])

            # If the current node is the target, we have found the path
            if current_frontier == current_target:
                return path_frontier[current_frontier] + path_target[current_target][::-1]

            # Mark the current node as closed
            open_set_frontier.remove(current_frontier)
            open_set_target.remove(current_target)
            closed_set_frontier.add(current_frontier)
            closed_set_target.add(current_target)

            # Explore neighbors of the current node
            for neighbor in graph.get(current_frontier, []):
                if neighbor not in closed_set_frontier:
                    open_set_frontier.add(neighbor)
                    new_cost = cost_frontier[current_frontier] + 1
                    if neighbor not in cost_frontier or new_cost < cost_frontier[neighbor]:
                        path_frontier[neighbor] = path_frontier[current_frontier] + [neighbor]
                        cost_frontier[neighbor] = new_cost

            for neighbor in graph.get(current_target, []):
                if neighbor not in closed_set_target:
                    open_set_target.add(neighbor)
                    new_cost = cost_target[current_target] + 1
                    if neighbor not in cost_target or new_cost < cost_target[neighbor]:
                        path_target[neighbor] = path_target[current_target] + [neighbor]
                        cost_target[neighbor] = new_cost

        return None

    # Start the bidirectional search
    return bidirectional_search(start, goal)

