    # Initialize f scores (estimated total cost from start to goal)
    f_score_start = {node: float('inf') for node in graph}
    f_score_goal = {node: float('inf') for node in graph}
    f_score_start[start] = heuristic(start, goal)
    f_score_goal[goal] = heuristic(goal, start)

    while open_set_start and open_set_goal:
        # Choose the node with the lowest f score from both open sets
        current_start = min(open_set_start, key=lambda x: f_score_start[x])
        current_goal = min(open_set_goal, key=lambda x: f_score_goal[x])

        # If we found the goal, we are done
        if current_start == current_goal:
            return reconstruct_path(came_from_start, came_from_goal, current_start)

        # Mark the current node as visited
        open_set_start.discard(current_start)
        open_set_goal.discard(current_goal)
        closed_set_start.add(current_start)
        closed_set_goal.add(current_goal)

        # Explore neighbors
