                f_score_start[neighbor] = tentative_g_score + heuristic(neighbor, start)
                if neighbor not in open_set_start:
                    open_set_start.add(neighbor)

    # If the loop exits, the goal is unreachable
    return None

def heuristic(node, goal):
    # Simple heuristic: Manhattan distance
    return abs(node[0] - goal[0]) + abs(node[1] - goal[1])

