def find_path(graph, start, goal):
    # Initialize the sets for the forward and backward searches
    forward = {start}
    backward = {goal}

    # Initialize the sets of visited nodes for both directions
    forward_visited = {start}
    backward_visited = {goal}

    # Initialize the sets of predecessor nodes
    forward_predecessors = {start: None}
    backward_predecessors = {goal: None}

    # Initialize the set of expanded nodes
    expanded = set()

    while forward and backward:
        # Move forward in the search
        if len(forward) > len(backward):
            current = forward.pop()
            next_nodes = graph[current]
            for node in next_nodes:
                if node not in forward_visited:
                    forward.add(node)
                    if node in backward_visited:
                        return expand_path(backward_predecessors, node, expanded)
                    forward_visited.add(node)
                    forward_predecessors[node] = current
        else:
            current = backward.pop()
            next_nodes = graph[current]
            for node in next_nodes:
                if node not in backward_visited:
                    backward.add(node)
                    if node in forward_visited:
                        return expand_path(forward_predecessors, node, expanded)
                    backward_visited.add(node)
                    backward_predecessors[node] = current

    # If the search completes without finding a path
    return None

def expand_path(predecessors, node, expanded):
    path = []
    while node is not None:
        path.append(node)
        node = predecessors[node]
    path.reverse()
    return path

